function cpuPick(){ var m=['rock','paper','scissors']; return m[Math.floor(Math.random()*3)]; }
function play(user, cpu){
  if(user===cpu) return 'tie';
  if((user==='rock'&&cpu==='scissors')||(user==='scissors'&&cpu==='paper')||(user==='paper'&&cpu==='rock')) return 'win';
  return 'lose';
}
var EXPORTS={play:play,cpuPick:cpuPick};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RockPaperScissorsForgePure = EXPORTS; }
